from pathlib import Path
root = Path(__file__).parent
checks = []
def check(name, ok): checks.append((name, bool(ok)))

uploads = (root/'src/uploads/uploads.service.ts').read_text()
upload_entity = (root/'src/uploads/upload-asset.entity.ts').read_text()
upload_controller = (root/'src/uploads/uploads.controller.ts').read_text()
upload_module = (root/'src/uploads/uploads.module.ts').read_text()
records = (root/'src/medical-records/medical-records.service.ts').read_text()
controller = (root/'src/medical-records/medical-records.controller.ts').read_text()
module = (root/'src/medical-records/medical-records.module.ts').read_text()
attachment = (root/'src/medical-records/medical-record-attachment.entity.ts').read_text()
consent = (root/'src/medical-records/medical-record-share-consent.entity.ts').read_text()
dto = (root/'src/medical-records/dto/create-medical-share-consent.dto.ts').read_text()
log = (root/'src/medical-records/medical-record-access-log.entity.ts').read_text()
app = (root/'src/app.module.ts').read_text()
data_source = (root/'src/database/data-source.ts').read_text()
migration = (root/'src/database/migrations/1734300000000-ExtendMedicalRecordsSharingAndAttachments.ts').read_text()
docs = (root/'docs/phase-v82-secure-medical-attachments-and-consent.md').read_text()

check('medical attachment category registered', "MEDICAL_ATTACHMENT = 'medical_attachment'" in upload_entity)
check('medical upload patient-only', "role !== 'patient'" in uploads and 'المرفقات الطبية مخصصة للمريض فقط' in uploads)
check('medical uploads accept PDF and supported images', "['image/jpeg', 'image/png', 'image/webp', 'application/pdf']" in uploads)
check('medical uploads remain private', 'isPublic: expectedImage' in uploads and 'expectedImage = IMAGE_CATEGORIES.includes(category)' in uploads)
check('signature validation retained', 'matchesSignature(buffer, dto.mimeType)' in uploads)
check('file size is bounded', '10 * 1024 * 1024' in uploads)
check('private storage uses random key and restrictive modes', 'randomUUID()' in uploads and 'mode: 0o700' in uploads and 'mode: 0o600' in uploads)
check('attachment entity links record, asset and uploader', all(x in attachment for x in ['recordId', 'uploadAssetId', 'attachedByUserId']))
check('attachment asset can only be linked once', 'uq_medical_record_attachment_asset' in attachment and 'findOne({ where: { uploadAssetId } })' in records)
check('patient can link only own active record', "actor.role !== UserRole.PATIENT" in records and "patientUserId: actor.sub, deletedAt: IsNull()" in records)
check('only own private medical upload can be linked', 'ownerUserId: actor.sub, category: UploadCategory.MEDICAL_ATTACHMENT, isPublic: false' in records)
check('consent stores doctor and selected record IDs', 'doctorUserId' in consent and 'recordIds' in consent)
check('consent has expiry, revocation and download flag', all(x in consent for x in ['expiresAt', 'revokedAt', 'allowDownload']))
check('consent DTO validates IDs, array size and expiry', all(x in dto for x in ['ArrayMinSize(1)', 'ArrayMaxSize(50)', 'IsDateString()', "IsUUID('4', { each: true })"]))
check('only approved doctor can receive grant', 'DoctorProfileStatus.APPROVED' in records)
check('consent max duration is 30 days', '30 * 24 * 60 * 60 * 1000' in records)
check('patient-only grant and revocation', "actor.role !== UserRole.PATIENT" in records and 'سحب الموافقة متاح للمريض فقط' in records)
check('revocation timestamp is persisted', 'consent.revokedAt = new Date()' in records)
check('doctor inbox filters active unexpired consent', 'c.revokedAt IS NULL AND c.expiresAt > NOW()' in records and 'sharedWithMe' in records)
check('doctor attachment metadata requires exact record consent', "':recordId = ANY(c.recordIds)'" in records)
check('download requires explicit allowDownload', "c.allowDownload = true" in uploads)
check('download rechecks active consent and record state', 'c.revokedAt IS NULL AND c.expiresAt > NOW()' in uploads and 'deletedAt: IsNull()' in uploads)
check('download URL omitted when consent disallows download', 'downloadUrl: canDownload ?' in records)
check('download action is audited', "action: 'attachment_download'" in uploads)
check('audit action capacity expanded', 'length: 32' in log and 'ALTER COLUMN "action" TYPE varchar(32)' in migration)
check('access history exposes actor identity', 'actorUserId: true' in records)
check('owner remains excluded from medical records', "actor.role === UserRole.OWNER" in records and 'المالك لا يملك صلاحية السجلات الطبية' in records)
check('controller exposes sharing and attachment routes', all(x in controller for x in ['share-consents', 'shared-with-me', ':id/attachments']))
check('upload controller allows patient role route', 'UserRole.PATIENT' in upload_controller)
check('repositories registered in modules, app and migration data source', all(x in module for x in ['MedicalRecordAttachment', 'MedicalRecordShareConsent', 'UploadAsset', 'DoctorProfile']) and all(x in upload_module for x in ['MedicalRecordAttachment', 'MedicalRecordShareConsent', 'MedicalRecordAccessLog', 'MedicalRecord']) and all(x in app for x in ['MedicalRecordAttachment', 'MedicalRecordShareConsent']) and all(x in data_source for x in ['MedicalRecord', 'MedicalRecordAccessLog', 'MedicalRecordAttachment', 'MedicalRecordShareConsent']))
check('migration creates attachment and consent tables with indexes', all(x in migration for x in ['CREATE TABLE "medical_record_attachments"', 'CREATE TABLE "medical_record_share_consents"', 'CREATE INDEX']))
check('migration uses foreign keys to existing private assets and records', all(x in migration for x in ['REFERENCES "medical_records"', 'REFERENCES "upload_assets"', 'REFERENCES "users"']))
check('documentation explains migration and production limitations', 'Run migration' in docs and 'malware scanning' in docs)

for name, ok in checks:
    print(('PASS' if ok else 'FAIL') + ' ' + name)
print(f'RESULT {sum(ok for _, ok in checks)}/{len(checks)}')
raise SystemExit(0 if all(ok for _, ok in checks) else 1)
